	@Inject
	public WorkloadGrammarAccess(GrammarProvider grammarProvider,
			TerminalsGrammarAccess gaTerminals) {
		this.grammar = internalFindGrammar(grammarProvider);
		this.gaTerminals = gaTerminals;
		this.pWorkloadModel = new WorkloadModelElements();
		this.pImport = new ImportElements();
		this.pWorkload = new WorkloadElements();
		this.pParam = new ParamElements();
		this.pDomain = new DomainElements();
		this.pTableData = new TableDataElements();
		this.pRows = new RowsElements();
		this.pPerRows = new PerRowsElements();
		this.pOverRows = new OverRowsElements();
		this.pColumnMap = new ColumnMapElements();
		this.pKeyPath = new KeyPathElements();
		this.pDistribution = new DistributionElements();
		this.pTransaction = new TransactionElements();
		this.pStep = new StepElements();
		this.pLet = new LetElements();
		this.pDraw = new DrawElements();
		this.pRepeat = new RepeatElements();
		this.pStatement = new StatementElements();
		this.pJoin = new JoinElements();
		this.pJoinOn = new JoinOnElements();
		this.pCondition = new ConditionElements();
		this.pColumnRef = new ColumnRefElements();
		this.pVarRef = new VarRefElements();
		this.pNum = new NumElements();
		this.pDecimal = new DecimalElements();
		this.pCount = new CountElements();
		this.eQueryType = new QueryTypeElements();
		this.eOperator = new OperatorElements();
		this.eLink = new LinkElements();
		this.pValidID = new ValidIDElements();
	}
	
	protected Grammar internalFindGrammar(GrammarProvider grammarProvider) {
		Grammar grammar = grammarProvider.getGrammar(this);
		while (grammar != null) {
			if ("io.shardml.Workload".equals(grammar.getName())) {
				return grammar;
			}
			List<Grammar> grammars = grammar.getUsedGrammars();
			if (!grammars.isEmpty()) {
				grammar = grammars.iterator().next();
			} else {
				return null;
			}
		}
		return grammar;
	}
	
	@Override
	public Grammar getGrammar() {
		return grammar;
	}
	
	
	public TerminalsGrammarAccess getTerminalsGrammarAccess() {
		return gaTerminals;
	}

	
